python3 - <<'EOF'
import re
base = "IP/IO/ICsprout_55LLULP1233_IO_251013/liberty/"
files = {
    "tt": "ICSIOA_N55_3P3_tt_1p2_3p3_25c.lib",
    "ff": "ICSIOA_N55_3P3_ff_1p32_3p63_125c.lib",
    "ss": "ICSIOA_N55_3P3_ss_1p08_2p97_125c.lib",
}
def pin_cap(text, cell, pin):
    # locate cell block
    cm = re.search(r'cell \("%s"\) \{' % cell, text)
    seg = text[cm.start():]
    pm = re.search(r'pin \(%s\) \{' % pin, seg)
    pseg = seg[pm.start():]
    # cut at next pin/cell
    end = re.search(r'\n\t(pin|cell) \(', pseg)
    pseg = pseg[:end.start()] if end else pseg
    out = {}
    for k in ("capacitance", "rise_capacitance", "fall_capacitance"):
        m = re.search(r'%s : ([0-9.e+-]+)' % k, pseg)
        out[k] = float(m.group(1))
    return out

data = {}
for c, f in files.items():
    t = open(base + f).read()
    data[c] = {p: pin_cap(t, "P65_1233_PAR", p) for p in ("PAD", "A")}
    print(c, data[c])

print()
for p in ("PAD", "A"):
    for k in ("capacitance", "rise_capacitance", "fall_capacitance"):
        ff, ss = data["ff"][p][k], data["ss"][p][k]
        print(f"{p}.{k}: ff={ff:.3f} ss={ss:.3f} ff-ss偏差={(ff-ss)/ss*100:+.1f}%")
EOF

